function handleChange(e){if(e.target.matches('[data-subtask-check]')){const t=taskById(activeTaskId),s=t.subtasks.find(x=>x.id===e.target.dataset.subtaskCheck);if(s){s.done=e.target.checked;persist();renderSubtasks(t);render()}}}
function handleDrag(){document.addEventListener('dragstart',e=>{const card=e.target.closest('[data-task]');if(!card)return;dragTaskId=card.dataset.task;card.classList.add('dragging');e.dataTransfer.effectAllowed='move'});document.addEventListener('dragend',e=>{e.target.closest('[data-task]')?.classList.remove('dragging');$$('.dragover').forEach(x=>x.classList.remove('dragover'));dragTaskId=null});document.addEventListener('dragover',e=>{const list=e.target.closest('[data-list]');if(!list)return;e.preventDefault();list.classList.add('dragover')});document.addEventListener('dragleave',e=>e.target.closest('[data-list]')?.classList.remove('dragover'));document.addEventListener('drop',e=>{const list=e.target.closest('[data-list]');if(!list||!dragTaskId)return;e.preventDefault();moveTask(dragTaskId,list.dataset.list);list.classList.remove('dragover')})}
$('#board-picker-btn').addEventListener('click',()=>openDialog('board-picker-dialog'));
$('#toggle-search').addEventListener('click',()=>{const p=$('#search-panel');p.hidden=!p.hidden;if(!p.hidden)setTimeout(()=>$('#search').focus(),0)});
$('#open-settings').addEventListener('click',openSettings);
$('#new-task-top').addEventListener('click',()=>openQuick(state.activeColumnId));
$('#create-board').addEventListener('click',createBoard);
$('#quick-form').addEventListener('submit',e=>{e.preventDefault();const title=$('#quick-title').value.trim();if(!title)return;const t=createTask(title,$('#quick-status').value);closeDialog('quick-dialog');openTask(t.id)});
$('#search').addEventListener('input',render);
$('.filter-row').addEventListener('click',e=>{const btn=e.target.closest('[data-filter]');if(!btn)return;const f=btn.dataset.filter;if(f==='all')state.filters=[];else state.filters=state.filters.includes(f)?state.filters.filter(x=>x!==f):[...state.filters,f];render()});
$('#task-title').addEventListener('input',e=>{autoSize(e.target);queueSave()});$('#task-description').addEventListener('input',e=>{autoSize(e.target);queueSave()});['task-status','task-assignee','task-priority'].forEach(id=>$(`#${id}`).addEventListener('change',queueSave));
$('#subtask-form').addEventListener('submit',e=>{e.preventDefault();addSubtask($('#subtask-input').value)});$('#comment-form').addEventListener('submit',e=>{e.preventDefault();addComment($('#comment-input').value)});
$('#duplicate-task').addEventListener('click',duplicateTask);$('#delete-task').addEventListener('click',deleteTask);
$('#add-column').addEventListener('click',addColumn);$('#add-tag-form').addEventListener('submit',e=>{e.preventDefault();addDraftTag($('#new-tag-input').value)});$('#save-settings').addEventListener('click',saveSettings);$('#duplicate-board').addEventListener('click',duplicateBoard);$('#delete-board').addEventListener('click',deleteBoard);
$('#stress-250').addEventListener('click',()=>stressAdd(250));$('#stress-1000').addEventListener('click',()=>stressAdd(1000));$('#self-test').addEventListener('click',selfTest);$('#clear-board').addEventListener('click',clearBoard);$('#reset-all').addEventListener('click',resetAll);$('#toast-undo').addEventListener('click',undoLast);
document.addEventListener('click',handleClick);document.addEventListener('change',handleChange);document.addEventListener('keydown',e=>{if(e.key==='Escape')return;const typing=['INPUT','TEXTAREA','SELECT'].includes(document.activeElement?.tagName);if(!typing&&e.key.toLowerCase()==='n'){e.preventDefault();openQuick(state.activeColumnId)}if(!typing&&e.key==='/'){e.preventDefault();$('#search-panel').hidden=false;$('#search').focus()}if((e.key==='Enter'||e.key===' ')&&e.target.matches('[data-task]')){e.preventDefault();openTask(e.target.dataset.task)}});handleDrag();render();persist();
